L["1 item on the bar"] = "1 objet sur la barre"
L["1 minute"] = "1 minute"
L["1 paladin in your group"] = "1 paladin dans votre groupe"
L["1 player has their own blessing"] = "1 joueur a sa propre bénédiction"
L["1 profile on this account"] = "1 profil sur ce compte"
L["1 raid"] = "1 raid"
L["1 runs Naowh Forever"] = "1 utilise Naowh Forever"
L["1 setting changed from its default"] = "1 option modifiée par rapport à sa valeur par défaut"
L["1 spell"] = "1 sort"
L["1 Unspent Talent Point"] = "1 point de talent non dépensé"
L["1. PICK YOUR BARS"] = "1. CHOISISSEZ VOS BARRES"
L["100%  (default)"] = "100%  (par défaut)"
L["100%, native resolution"] = "100%, résolution native"
L["12-hour clock"] = "Horloge 12 heures"
L["16x Anisotropic"] = "Anisotrope 16x"
L["2. ALSO KEEP"] = "2. CONSERVER AUSSI"
L["24-Hour Clock"] = "Horloge 24 heures"
L["24-hour clock"] = "Horloge 24 heures"
L["3. NAME AND SAVE"] = "3. NOMMER ET ENREGISTRER"
L["30, while the game is not in focus"] = "30, quand le jeu n'est pas au premier plan"
L[": copy ID or Wowhead link"] = ": copier l'ID ou le lien Wowhead"
L[": mail expiring soon on "] = ": courrier expirant bientôt sur "
L["; buys at vendors"] = "; achète chez les marchands"
L["<AFK>"] = "<ABS>"
L["<DND>"] = "<NPD>"
L["[Where?]"] = "[Où ?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "Un /thank à tous ceux autour de vous quand le jeu ne peut pas nommer le lanceur."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Un lien [Où ?] après un chuchotement de quelqu'un dont la zone est inconnue. Cliquer dessus lance un /who sur lui et affiche sa zone ; ses messages suivants sont étiquetés."
L["A banner and a sound when one of them joins your group."] = "Une bannière et un son quand l'un d'eux rejoint votre groupe."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Une barre au niveau de menace où vous prendriez l'aggro, pour lire facilement l'écart."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Une barre pour les coups de votre cible, relancée à chaque coup physique que vous subissez pendant qu'elle vous cible, et raccourcie quand elle pare. C'est une estimation : le jeu ne dit pas qui vous a frappé ni avec quoi, donc d'autres attaquants, des techniques physiques et des saignements la relancent aussi."
L["A bar left out is not touched by an import."] = "Une barre omise n'est pas touchée par une importation."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Une barre par membre du groupe avec son niveau et sa progression. Tout membre utilisant Naowh Forever partage son expérience, même avec cette option désactivée ; les autres affichent leur niveau. Les mises à jour attendent la fin du combat. Déplacez-la dans l'éditeur d'ATH."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Une barre avec le nom, une flèche de direction et la distance, tant qu'un point de passage est défini."
L["A batch of ten, four done, as it shows while you craft."] = "Un lot de dix, quatre faits, tel qu'il s'affiche pendant la fabrication."
L["A black outline round the clock."] = "Un contour noir autour de l'horloge."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Un contour noir autour de l'affichage IPS / MS et des compteurs, à la place de l'ombre douce."
L["A black outline round the text, in place of the soft shadow."] = "Un contour noir autour du texte, à la place de l'ombre douce."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Un bouton par ensemble : cliquez pour l'équiper, Maj-clic pour y enregistrer ce que vous portez, Ctrl-clic pour le renommer, clic droit pour changer son icône, et + pour en enregistrer un nouveau. L'ensemble porté est entouré. Déplacez-le dans l'éditeur d'ATH."
L["A button that flags or unflags you for PvP, showing which you are."] = "Un bouton qui active ou désactive votre JcJ et montre votre état."
L["A campfire in range and Camp Benefits about to run out."] = "Un feu de camp à portée et les Avantages du camp sur le point d'expirer."
L["A campfire in range and no Camp Benefits."] = "Un feu de camp à portée et pas d'Avantages du camp."
L["A campfire is in range"] = "Un feu de camp est à portée"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Une carte derrière le texte, un fondu sombre doux, ou rien du tout."
L["A card over the pin with what it is and how far."] = "Une carte au-dessus du marqueur indiquant ce que c'est et à quelle distance."
L["A cast part way through, swept around the ring."] = "Une incantation en cours, balayée autour de l'anneau."
L["A cast someone interrupted, held for the fade time."] = "Une incantation interrompue par quelqu'un, maintenue pendant la durée du fondu."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Une incantation pendant que votre interruption est en recharge, avec le repère de son retour."
L["A cast while your interrupt is ready."] = "Une incantation pendant que votre interruption est prête."
L["A cast you cannot interrupt, with its shield."] = "Une incantation que vous ne pouvez pas interrompre, avec son bouclier."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Un personnage apparaît ici après une connexion avec Suivi des instances activé. Suivre les rerolls affiche les autres : expérience de repos et durabilité, depuis la dernière connexion de ce personnage."
L["A choice among its rewards: pick this one."] = "Un choix parmi ses récompenses : prenez celle-ci."
L["A command name can only use letters, numbers and underscores."] = "Un nom de commande ne peut contenir que des lettres, des chiffres et des tirets bas."
L["A consumable or personal buff with less time than this left counts as missing."] = "Un consommable ou une amélioration personnelle avec moins de temps restant que ceci compte comme manquant."
L["A crosshair at the middle of your screen."] = "Un réticule au centre de votre écran."
L["A cup beside a healer who is drinking."] = "Une coupe à côté d'un soigneur qui boit."
L["A custom command can't reload. Type /reload."] = "Une commande personnalisée ne peut pas recharger. Tapez /reload."
L["A dark or light fill and edge behind each line, or none."] = "Un fond et un bord sombres ou clairs derrière chaque ligne, ou aucun."
L["A dark panel behind the icons."] = "Un panneau sombre derrière les icônes."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Une porte sur chaque entrée de donjon et de raid sur la carte du monde, pour les factions listées par le Journal. Survolez-la pour les niveaux, cliquez pour un point de passage."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Un point sur un emplacement où un meilleur enchantement pour votre niveau vous attend : survolez-le pour le conseil, cliquez pour demander dans Commerce."
L["A fading trail behind the cursor."] = "Une traînée qui s'estompe derrière le curseur."
L["A few quick steps for %s only, its own modules included."] = "Quelques étapes rapides pour %s uniquement, modules compris."
L["A game that opens when a flight starts and closes when you land."] = "Un jeu qui s'ouvre au début d'un vol et se ferme à l'atterrissage."
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "Un jeu pour passer le vol : le quiz ou l'entraînement à la visée. Il se ferme à l'atterrissage."
L["A gear set called %s already exists."] = "Un ensemble nommé %s existe déjà."
L["A glow on the moving edge of the fill."] = "Une lueur sur le bord mobile du remplissage."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Une chaîne de quêtes cachée à travers Azeroth : cliquez tour à tour sur chaque élément dans le monde. Elle rapporte beaucoup d'expérience et se termine par le Sac de couchage douillet ; reposez-vous dedans pour un bonus d'expérience."
L["A key that opens Group Inspect."] = "Une touche qui ouvre l'inspection du groupe."
L["A key that shows a boss's loot at your cursor."] = "Une touche qui affiche le butin d'un boss à votre curseur."
L["A key that uses this item."] = "Une touche qui utilise cet objet."
L["A later point needs it. "] = "Un point ultérieur en dépend. "
L["A later step."] = "Une étape ultérieure."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Une ligne pour chaque quête rendue, avec l'expérience et l'argent rapportés. Les objets de récompense ont leur propre ligne."
L["A line for every reputation gain, from quests and kills alike."] = "Une ligne pour chaque gain de réputation, des quêtes comme des victimes."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Une ligne pour l'expérience de chaque victime. L'expérience de quête figure sur la ligne de la quête."
L["A line from the pin down to a map pin's or corpse's spot."] = "Une ligne du marqueur jusqu'à l'emplacement d'un marqueur de carte ou d'un cadavre."
L["A line in chat with the item's link."] = "Une ligne dans la discussion avec le lien de l'objet."
L["A line in their color on their player tooltip."] = "Une ligne à leur couleur dans leur infobulle de joueur."
L["A line to share them with."] = "Une ligne pour les partager."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Une ligne sous l'ID indiquant quelles touches la copient (Ctrl-Maj-C : copier l'ID ou le lien Wowhead). Désactivé, le raccourci fonctionne toujours ; la ligne n'est simplement pas affichée."
L["A look you do not have yet|r"] = "Un style que vous n'avez pas encore|r"
L["a macro made on this character"] = "une macro créée sur ce personnage"
L["A macro this character does not have yet: the import makes it."] = "Une macro que ce personnage n'a pas encore : l'importation la crée."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Un bouton de minicarte qui ouvre %s. /nf%s fait de même, et la barre du haut peut aussi l'accueillir. Enregistré pour cet ordinateur."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Une ligne de poids Naowh, ou un export EP de WoWSims (dans WoWSims : Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Une ligne de poids Naowh, ou un export EP de WoWSims."
L["A new session, before any experience."] = "Une nouvelle session, avant toute expérience."
L["A parry by your target took 40% off its swing."] = "Une parade de votre cible a réduit son coup de 40%."
L["A party of five, a card each."] = "Un groupe de cinq, une carte chacun."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "Le score d'un joueur dans son infobulle. Un joueur utilisant Naowh Forever partage le sien ; celui des autres est lu sur leur équipement quand vous les survolez, à portée d'inspection et hors combat."
L["A profile"] = "Un profil"
L["a quest"] = "une quête"
L["A quest reward for the other faction; try the Auction House."] = "Une récompense de quête de l'autre faction ; essayez l'hôtel des ventes."
L["A raid for %d players"] = "Un raid pour %d joueurs"
L["A raid, a row each."] = "Un raid, une ligne chacun."
L["A rare someone else is fighting."] = "Un rare que quelqu'un d'autre combat."
L["A rare you have killed before."] = "Un rare que vous avez déjà tué."
L["A rare you have not killed yet."] = "Un rare que vous n'avez pas encore tué."
L["A reward from the quest "] = "Une récompense de la quête "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Un anneau autour de votre curseur pour ne jamais le perdre dans un combat chargé, avec votre temps de recharge global et vos incantations qui le balayent."
L["A round in progress."] = "Une manche en cours."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Une rangée d'icônes pour les améliorations manquantes de nourriture, flacon, élixir et parchemin, votre propre amélioration de classe et les améliorations de classe manquantes dans votre groupe. Hors combat uniquement : en combat, le jeu cache vos améliorations aux addons, les icônes gardent donc leur dernier état. Survolez-en une pour choisir un objet transporté à utiliser. Déplacez-les dans l'éditeur d'ATH."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Un compteur d'or par heure à côté de la ligne la plus récente, comptant l'argent et la valeur des objets depuis votre premier butin de la session."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Un bouton Analyser les prix à l'hôtel des ventes. Il lit chaque annonce et retient le prix d'achat immédiat le plus bas pour chaque objet, pour ce royaume et cette faction. Blizzard autorise une analyse complète toutes les 15 minutes."
L["A junk icon on the bag slot of each item marked as junk."] = "Une icône de camelote sur l'emplacement de sac de chaque objet marqué comme camelote."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Un second panneau pour votre focalisation, pour garder la durée d'Assommer ou de Métamorphose sur un ennemi pendant que vous en combattez un autre."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Un ensemble qui s'équipe tout seul quand vous êtes sur une monture ou au repos, et l'ensemble précédent revient ensuite."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Un jeu de tir pour les vols : cliquez le plus vite possible sur les races de l'autre faction."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Un bref texte en entrant et en sortant du combat. Déplacez-le dans l'éditeur d'ATH."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Une petite barre avec votre prochaine visite chez l'entraîneur et votre or, à laisser affichée pendant la progression. Déplacez-la en la faisant glisser."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Une petite barre de vie pour l'autre tank de votre groupe, affichée quand vous tankez : rôle de tank, Forme d'ours, Posture défensive ou Fureur vertueuse. L'autre tank est celui qui a le rôle de tank ou l'assignation de tank principal du raid. Cliquez dessus pour le cibler. Les changements faits en combat s'appliquent à la fin du combat. Déplacez-la dans l'éditeur d'ATH."
L["A soft glow around Naowh's arrow."] = "Une lueur douce autour de la flèche de Naowh."
L["A soft glow beside each icon."] = "Une lueur douce à côté de chaque icône."
L["A soft glow round it in your accent color."] = "Une lueur douce autour, dans votre couleur d'accent."
L["A soft glow round it in your rank's color."] = "Une lueur douce autour, dans la couleur de votre rang."
L["A soft ring pulses around each target."] = "Un anneau doux pulse autour de chaque cible."
L["a sound to refresh"] = "un son pour renouveler"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Un son, ou le texte vocal lu à voix haute, au début de chaque incantation."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Un son, ou le texte vocal lu à voix haute. La synthèse vocale peut provoquer des saccades sur certains PC, car le jeu attend pendant que Windows parle ; un son ne coûte rien."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Un sort qu'une importation n'a pas pu placer parce que vous ne le connaissez pas encore va dans son emplacement enregistré quand vous l'apprenez, sauf si vous y avez mis autre chose."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Un bouton Empiler sur la carte quand des piles partielles d'un objet peuvent être réunies."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Une étoile sur la carte du monde pour chaque rare que vous n'avez pas tué, là où il a le plus de chances d'être. Survolez-en une pour le rare et ses butins, ses autres points d'apparition et, s'il patrouille, son trajet ; cliquez pour un point de passage, clic droit pour garder ses points et son trajet affichés."
L["A string to share it with."] = "Une chaîne pour la partager."
L["A supporter"] = "Un soutien"
L["A team member"] = "Un membre de l'équipe"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Un texte sur la barre : cliquez dessus dans l'aperçu pour le changer. Chaque texte s'affiche à un seul endroit sur la barre : en choisir un affiché ailleurs le déplace ici."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Un repère sur la barre là où votre interruption sort de recharge. Masqué quand elle est prête."
L["A title bar naming the mob the threat is on."] = "Une barre de titre nommant le monstre visé par la menace."
L["A trained spell drops into its saved slot."] = "Un sort appris se place dans son emplacement enregistré."
L["a vendor sells the formula"] = "un marchand vend la formule"
L["A warning when a rare is near"] = "Un avertissement quand un rare est proche"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Un avertissement quand un rare est proche de vous : quand sa barre d'info apparaît, que vous le survolez ou le ciblez. Une carte avec son portrait : clic droit pour la fermer, et son marqueur place un point de passage vers le rare. Déplacez-la dans l'éditeur d'ATH."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Un avertissement quand un chasseur ou un démoniste n'a pas de familier. Un démoniste qui a sacrifié son démon n'est pas averti. Déplacez-le dans l'éditeur d'ATH."
L["A word of your own on the icon."] = "Un mot de votre choix sur l'icône."
L["A world drop from %d kinds of mob"] = "Un butin mondial sur %d |4type de monstre:types de monstres;"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Un quiz WoW pour les feux de camp et les vols, ou à tout moment avec /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Un ! jaune sur la carte du monde sur chaque donneur de quêtes ayant une quête que vous pouvez prendre et qui donne encore de l'expérience. Survolez-le pour les quêtes ; cliquez pour un point de passage."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Une zone plus ancienne n'est plus affichée, car le joueur est sans doute parti."
L["Abandon %s?"] = "Abandonner %s ?"
L["Abilities"] = "Techniques"
L["about "] = "environ "
L["about %d:%02d"] = "environ %d:%02d"
L["About %s at your last scan%s%s"] = "Environ %s lors de votre dernière analyse%s%s"
L["About %s spent"] = "Environ %s dépensés"
L["About a minute."] = "Environ une minute."
L["Above"] = "Au-dessus"
L["Acc."] = "Préc."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Accent : bénédiction de classe manquante. Plus clair : bientôt expirée. Plus foncé : seulement les joueurs avec la leur."
L["Accept Quests"] = "Accepter les quêtes"
L["Accept Shared Dungeon Quests"] = "Accepter les quêtes de donjon partagées"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Accepte une quête dès que son texte s'ouvre. Utilisez le modificateur pour la lire d'abord."
L["Accepts dungeon quests your group shares with you straight away."] = "Accepte immédiatement les quêtes de donjon que votre groupe partage avec vous."
L["Accepts shared quests"] = "Accepte les quêtes partagées"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Accepte la fenêtre à l'écran : une invocation, une résurrection, une invitation de groupe."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Accepte, rend et partage les quêtes pour vous, et retient la récompense enregistrée pour une quête. Le modificateur les saute ou les déclenche, selon Effet du modificateur."
L["Account"] = "Compte"
L["Account "] = "Compte "
L["Account macros"] = "Macros du compte"
L["Account this hour: %d of %d"] = "Compte cette heure-ci : %d sur %d"
L["Accuracy"] = "Précision"
L["Action Bars is switched off."] = "Barres d'action est désactivé."
L["Action Bars' own window, with your class's saved sets."] = "La fenêtre propre de Barres d'action, avec les configurations enregistrées de votre classe."
L["Active"] = "Actif"
L["Activity Bar"] = "Barre d'activité"
L["Activity Bar Color"] = "Couleur de la barre d'activité"
L["Activity Bar Height"] = "Hauteur de la barre d'activité"
L["Add %d item to your junk list: %s%s?"] = "Ajouter %d objet à votre liste de camelote : %s%s ?"
L["Add %d items to your junk list: %s%s?"] = "Ajouter %d objets à votre liste de camelote : %s%s ?"
L["Add %d macro as character macros?%s"] = "Ajouter %d macro comme macro de personnage ?%s"
L["Add %d macros as character macros?%s"] = "Ajouter %d macros comme macros de personnage ?%s"
L["Add %s"] = "Ajouter %s"
L["Add %s (%d items) as a new BiS list?"] = "Ajouter %s (%d objets) comme nouvelle liste BiS ?"
L["Add %s to the Consumable Bar?"] = "Ajouter %s à la barre de consommables ?"
L["Add a backup pick"] = "Ajouter un choix de secours"
L["Add a Button"] = "Ajouter un bouton"
L["Add a stat"] = "Ajouter une caractéristique"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Ajoutez un ID d'objet, ou importez une liste. La nourriture compte toute amélioration Bien nourri et les autres objets leur propre amélioration ; ajoutez des ID de sort d'amélioration seulement pour un objet qui en donne une autre. Rien n'est ajouté automatiquement. Survolez un rappel pour choisir un objet configuré dans vos sacs. Les rappels sont en pause en combat ; les menus d'objets fonctionnent hors combat. Quand et où ils s'affichent se règle dans AuraBuffs > Options."
L["Add consumables, put them in order, and set each one up."] = "Ajoutez des consommables, ordonnez-les et configurez chacun."
L["Add Items"] = "Ajouter des objets"
L["Add Latency"] = "Ajouter la latence"
L["Add macros someone shared with you."] = "Ajoutez des macros que quelqu'un a partagées avec vous."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Ajoutez ou retirez vos commandes, activez ou désactivez chacune, ou restaurez les valeurs par défaut."
L["Add Slash Command"] = "Ajouter une commande slash"
L["Add the %s build %s (%d points)?"] = "Ajouter le build %s %s (%d points) ?"
L["Add the consumables to watch in the AuraBuffs window."] = "Ajoutez les consommables à surveiller dans la fenêtre AuraBuffs."
L["Add Themes to RestedXP"] = "Ajouter des thèmes à RestedXP"
L["Add to BiS List"] = "Ajouter à la liste BiS"
