L["Add to the Left Side"] = "Ajouter à gauche"
L["Add to the Right Side"] = "Ajouter à droite"
L["Add your consumables, put them in order, set each one up."] = "Ajoutez vos consommables, ordonnez-les, configurez chacun."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Ajoutez vos propres lignes aux macros de sac. Elles sont conservées après l'objet, quel que soit le contenu de vos sacs."
L["Added %d consumable to the Consumable Bar."] = "%d consommable ajouté à la barre de consommables."
L["Added %d consumables to the Consumable Bar."] = "%d consommables ajoutés à la barre de consommables."
L["Added %d consumables; %d were already listed or past the %d limit."] = "%d consommables ajoutés ; %d étaient déjà listés ou au-delà de la limite de %d."
L["Added %d of %d: %s."] = "%d sur %d ajoutés : %s."
L["Added %d."] = "%d ajoutés."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "%s ajoutée à ce personnage. Faites-la glisser sur une barre depuis la fenêtre des macros du jeu (/macro)."
L["Added %s to your BiS %s as #%d."] = "%s ajouté à votre BiS %s en n° %d."
L["Added %s to your BiS %s."] = "%s ajouté à votre BiS %s."
L["Added next to your Library, never over it"] = "Ajouté à côté de votre bibliothèque, sans jamais l'écraser"
L["Added next to your own lists, never over them"] = "Ajouté à côté de vos propres listes, sans jamais les écraser"
L["Added next to your saved builds"] = "Ajouté à côté de vos builds enregistrés"
L["Adding Items"] = "Ajout d'objets"
L["Addon Font"] = "Police de l'addon"
L["Addon List"] = "Liste des addons"
L["Addon Memory"] = "Mémoire des addons"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Ajoute \"- [1] + Ajouter à la liste\" sous les composants d'une recette : les matériaux qu'Acheter à l'HV achèterait pour ce nombre de fabrications vont sur une liste d'achats, de n'importe où. À l'hôtel des ventes la liste s'affiche à côté : Vérifier les prix les consulte un par un et avertit en rouge quand l'un est bien au-dessus de votre dernière analyse, puis Tout acheter parcourt la liste un matériau à la fois, chacun n'étant acheté qu'après confirmation de son prix final. Un matériau que vous pouvez fabriquer moins cher à partir de ses composants, comme une barre à partir de minerai, voit plutôt ses composants achetés."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Ajoute une colonne Sacs aux composants de la recette choisie, indiquant combien de chacun vous portez."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Ajoute une colonne Banque aux composants de la recette choisie, indiquant combien de chacun sont dans votre banque."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Ajoute un bouton à la fenêtre qui remplace chaque rang inférieur sur vos barres par le plus haut rang que vous connaissez. Les barres clavier et manette restent au même emplacement. Clic droit sur un sort dans la fenêtre pour garder ses rangs inférieurs, pour le downranking. Les changements de rang ne se font que hors combat."
L["Adds a Land button to come down at the next stop on the way."] = "Ajoute un bouton Atterrir pour descendre au prochain arrêt du trajet."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Ajoute une ligne qui signale tout emplacement dont l'enchantement manque ou diffère de ceux capturés avec Capturer les enchantements actuels. Survolez-la pour les détails."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Ajoute à l'infobulle d'un sort à mana ses soins ou dégâts par point de mana et par seconde."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Ajoute un second nombre, orange, à côté de chaque recette : combien vous pourriez en fabriquer après avoir acheté les composants vendus par les marchands, comme le Flux faible ou le Fil grossier. Les composants de la recette indiquent alors combien de chacun acheter."
L["Adds how long the visit lasted."] = "Ajoute la durée de la visite."
L["Adds target and focus switching to the meter's title bar."] = "Ajoute le basculement cible / focalisation à la barre de titre de l'indicateur."
L["Adds the average experience here."] = "Ajoute l'expérience moyenne ici."
L["Adds the coins looted."] = "Ajoute l'argent ramassé."
L["Adds the consumables in your bags that are not on the bar yet."] = "Ajoute les consommables de vos sacs qui ne sont pas encore sur la barre."
L["Adds the deaths."] = "Ajoute les morts."
L["Adds the experience gained."] = "Ajoute l'expérience gagnée."
L["Adds the materials for one more craft."] = "Ajoute les matériaux pour une fabrication de plus."
L["Adds the Naowh themes to RestedXP's theme list."] = "Ajoute les thèmes Naowh à la liste des thèmes de RestedXP."
L["Adds the reputation gained."] = "Ajoute la réputation gagnée."
L["Adds the visits at this level."] = "Ajoute les visites à ce niveau."
L["Adds the visits until you level."] = "Ajoute les visites jusqu'au prochain niveau."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "Ajoute votre bonus aux soins ou aux dégâts des sorts ; désactivé, affiche les valeurs de base du sort."
