L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "Après une visite chez l'entraîneur, une petite fenêtre liste les techniques que vous venez d'apprendre. Celles apprises d'un tome ou d'une quête s'affichent un instant après. Faites-en glisser une de la fenêtre vers vos barres."
