L["Also keeps your last whispers and group chat lines with each player."] = "Conserve aussi vos derniers chuchotements et lignes de discussion de groupe avec chaque joueur."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "Ouvre aussi la carte du monde sur le point de passage, pour voir où il est. Hors combat uniquement."
L["Also prints the summary when you leave a raid."] = "Affiche aussi le résumé quand vous quittez un raid."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "Vous rappelle aussi en instance. Désactivé par défaut : peu en ont des herbes ou du minerai."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "Affiche aussi le bénéfice de chaque recette à droite de sa ligne dans la liste, en vert ou en rouge. Les recettes au bénéfice inconnu n'en affichent pas."
L["Also thanks players in your party or raid."] = "Remercie aussi les joueurs de votre groupe ou raid."
L["Also used inside dungeons and raids."] = "Utilisé aussi dans les donjons et raids."
L["Also warns about rares you have killed before."] = "Avertit aussi pour les rares déjà tués."
