L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "Alt-cliquez sur une récompense à choisir, dans le journal de quêtes ou chez le donneur de quêtes, pour l'enregistrer pour cette quête dans ce profil ; Alt-cliquez à nouveau pour l'effacer. Elle est sélectionnée quand vous rendez la quête, et Rendre les quêtes la prend pour vous."
L["Alt-click an item in your bags to mark it as junk, and sell it at the next vendor."] = "Alt-cliquez sur un objet de vos sacs pour le marquer comme camelote et le vendre au prochain marchand."
