L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "Une erreur \"L'inventaire est plein\" fait apparaître la rangée pendant 20 secondes, même avec plus d'emplacements libres que le seuil ci-dessus."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "Un reroll qui a déjà cette macro, par nom et texte ou par texte seul, utilise la sienne."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "Un bouton Rerolls à côté de l'onglet Envoyer de la boîte aux lettres liste vos personnages de ce royaume et de cette faction avec leur niveau et leur or. Choisissez-en un pour remplir le champ Destinataire."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "Un bouton Attacher à côté de l'onglet Envoyer de la boîte aux lettres : attachez toutes les fournitures d'artisanat, un type de fourniture, ou votre équipement non lié en un clic."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "Un ID que le jeu garde caché : Masquer la ligne le retire de l'infobulle, Afficher masqué affiche la ligne avec Masqué à la place du nombre."
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "Un objet qui vaut plus à l'hôtel des ventes que chez un marchand est évalué à son prix d'enchère, d'après votre dernière analyse des prix ou TradeSkillMaster."
