L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "Chez un entraîneur de métier qui enseigne l'une de vos recettes favorites que vous pouvez apprendre maintenant (étoile devant son nom, ou clic droit dans la liste), une fenêtre à côté de celle de l'entraîneur les liste avec leur coût : Apprendre pour une, ou Tout apprendre."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "Chez un marchand qui les vend, complète vos composants de classe et munitions jusqu'à la quantité à porter, et indique ce qui a été dépensé. Désactivé par défaut : il dépense de l'or pour vous."
L["At level %d"] = "Au niveau %d"
L["At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox."] = "À la connexion, nomme ceux de vos personnages dont le courrier expire dans les trois jours. Il connaît le courrier de chaque personnage depuis sa dernière ouverture d'une boîte aux lettres."
L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "À l'hôtel des ventes, une fenêtre à côté liste les patrons, plans et manuels de vos recettes favorites que vous n'avez ni appris ni achetés, avec leur prix actuel. Acheter trouve le moins cher et demande avant qu'Accepter l'achète."
