L["Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them, in place of the cast bar that fills for every craft. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer."] = "Fabriquer plusieurs objets à la fois (Tout créer, ou Créer avec un nombre) affiche une barre pour tout le lot, dessinée comme le minuteur de vol : la recette, combien sont faits et le temps restant pour tous, à la place de la barre d'incantation qui se remplit à chaque fabrication. Elle se place là où est le minuteur de vol, puisque personne ne fabrique en vol : déplacez-la dans l'éditeur d'ATH comme le minuteur de vol."
