L["Drag the right edge for width, a line's bottom for height. Wheel: text size (Shift: spacing, Ctrl: lines). Right-click a line for what it shows."] = "Faites glisser le bord droit pour la largeur, le bas d'une ligne pour la hauteur. Molette : taille du texte (Maj : espacement, Ctrl : lignes). Clic droit sur une ligne pour ce qu'elle affiche."
L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "Faites glisser le bord droit pour la largeur. Molette : taille du texte (Maj : hauteur). Cliquez sur un bonus ou la durée pour l'afficher ou le masquer. Clic droit pour plus."
L["Drag to make the map bigger or smaller.\nRight-click: back to 100%."] = "Faites glisser pour agrandir ou réduire la carte.\nClic droit : retour à 100%."
