L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "Le nom ou l'icône de chaque classe, sous son bouton ou à côté quand la barre est verticale."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Chaque visite de donjon ou de raid avec Suivi des instances activé : le temps passé à l'intérieur, l'argent ramassé et l'expérience gagnée. La réputation gagnée est listée sous la visite. Revenir dans le même groupe dans l'heure, avant de le réinitialiser, prolonge cette visite, et le temps passé dehors n'est pas compté. Les autres personnages restent enregistrés et s'affichent ici quand Suivre les rerolls est activé. Les réparations et ventes aux marchands ne sont pas comptées. Les visites les plus anciennes sortent du bas de la liste."
L["Each line fades out after %ss."] = "Chaque ligne s'estompe après %s s."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Chacune est une macro de compte. Placez-la une fois sur une barre et elle se tient à jour : ramassez une meilleure potion, invoquez de la nourriture fraîche ou ramassez des bandages, et la macro est réécrite pour utiliser le meilleur que vous portez.\n\nLe jeu ne permet pas de modifier les macros en plein combat, donc un changement pendant un combat attend sa fin."
L["Each point of the trail in a color of its own."] = "Chaque point de la traînée dans sa propre couleur."
L["Each slot's item level, in its icon's corner."] = "Le niveau d'objet de chaque emplacement, dans le coin de son icône."
L["Each visit, with its time, coins, and experience."] = "Chaque visite, avec sa durée, son argent et son expérience."
