L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "Pour les paladins, un bouton par classe de votre groupe. Clic gauche bénit le prochain membre de cette classe qui en a besoin, les manquants d'abord, en ignorant les morts et ceux hors de portée. Clic droit sur une classe pour choisir sa bénédiction ou ouvrir sa liste de joueurs. Déplacez-la dans l'éditeur d'ATH. L'aperçu permet de la modifier : clic droit sur une classe pour sa bénédiction, cliquez sur l'aura pour la choisir, molette pour la taille et Maj-molette pour l'espacement, faites glisser l'écart après l'aura, x masque un bouton et + le ramène."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Pour les personnages Skyborne : lignes telluriques (Alliance, pour Lecture des lignes telluriques) ou Convergences élémentaires (Horde, pour Vue céleste) marquées sur la carte du monde. Le jeu ne les marque pas : l'addon connaît celles trouvées par les joueurs, et enregistre chaque nouvelle sur laquelle vous lancez votre technique raciale. Les autres races ne voient aucun marqueur."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "Pour votre classe : importe cette configuration une fois sur un nouveau personnage, au niveau 1 sans expérience."
L["For your level"] = "Pour votre niveau"
L["Forget %s on %s? It comes back the next time you log in on it with a Mail & Alts option on."] = "Oublier %s sur %s ? Il revient à votre prochaine connexion sur ce personnage avec une option de Courrier et rerolls activée."
