L["How close a book has to be before it pings."] = "La distance à laquelle un livre doit se trouver pour signaler sa présence."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Combien de temps avant la fin du sort en cours vous pouvez appuyer sur le suivant, en millisecondes. 100 à 400 convient à la plupart : plus bas est plus réactif, plus haut tolère mieux la latence. Mêlée environ votre ping + 100, distance environ votre ping + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "À quel moment une icône commence à s'estomper, de 0% (tout de suite) à 95% (tout à la fin)."
L["How far below your level gear has to be for Old Common Gear."] = "De combien l'équipement doit être sous votre niveau pour Vieil équipement classique."
L["How Group Inspect shows a party and a raid, with sample players."] = "Comment l'inspection du groupe affiche un groupe et un raid, avec des joueurs d'exemple."
L["How little Camp Benefits time counts as needing a refresh."] = "Le temps restant des Avantages du camp en dessous duquel il faut les actualiser."
