L["How long before the effect runs out it shows again."] = "Combien de temps avant la fin de l'effet il réapparaît."
L["How long each line stays before it fades."] = "Durée de chaque ligne avant qu'elle s'estompe."
L["How long it takes to get there at your speed."] = "Le temps pour y aller à votre vitesse."
