L["Makes this recipe a favourite, or no longer one. Favourites get a star in the list, and the Filter menu's Favorites shows only them. Right-click a recipe in the list does the same."] = "Ajoute cette recette aux favoris, ou l'en retire. Les favoris ont une étoile dans la liste, et Favoris dans le menu Filtre n'affiche qu'eux. Un clic droit sur une recette de la liste fait de même."
