L["Once Per Player Every"] = "Une fois par joueur toutes les"
L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "Une fois l'hôtel des ventes analysé (Analyser les prix), la recette choisie indique le coût d'achat de ses composants, le prix de vente de l'objet, et le bénéfice après la taxe de 5% de l'hôtel des ventes. Chaque composant est compté à son prix le plus bas : le prix d'un marchand une fois que vous l'avez vu en vendre, sinon l'achat immédiat le plus bas de votre dernière analyse. Décochez un composant que vous avez déjà pour l'exclure du coût, pour chaque recette qui l'utilise. Survolez les lignes pour le détail."
L["One addon"] = "Un addon"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "Une barre par arme, réglée sur l'événement de coup propre au jeu, pour que l'accélération par parade, les remises à zéro de coup et la hâte soient toujours justes. Déplacez-les dans l'éditeur d'ATH."
L["One Fewer"] = "Un de moins"
L["One item per click: the game needs a click for every disenchant."] = "Un objet par clic : le jeu exige un clic pour chaque désenchantement."
L["One More"] = "Un de plus"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Un nombre pour l'équipement d'un personnage, sur l'échelle du niveau d'objet : 26.4 signifie un équipement valant un ensemble d'épiques de niveau 26. Le vôtre figure toujours sur le mannequin de la liste BiS."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Un chuchotement par ligne, choisi au hasard ; {buff} et {name} sont remplis."
