L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Ouvre le lien de métier d'un autre joueur dans cette fenêtre, pour lui commander des fabrications. Choisissez une recette, réglez le nombre de fabrications, cochez les matériaux que vous apportez (ou tapez la quantité), et Ajouter à la commande. La commande à droite a un pourboire suggéré par fabrication, modifiable ; Demander envoie à l'artisan un message par fabrication avec la quantité, vos matériaux et le pourboire : dans la discussion de groupe s'il est dans votre groupe, sinon en chuchotement. Les prix et le pourboire nécessitent une analyse de l'hôtel des ventes."
L["Opens its settings and leaves the HUD Editor."] = "Ouvre ses options et quitte l'éditeur d'ATH."
L["Opens the Aim Trainer now, out of combat."] = "Ouvre l'entraînement à la visée maintenant, hors combat."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Ouvre la fenêtre AuraBuffs, où vous ajoutez chaque objet par son ID d'objet et son ID de sort d'amélioration."
L["Opens the Consumable Bar's settings."] = "Ouvre les options de la barre de consommables."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Ouvre la carte de copie sur un sort d'exemple. Sélectionnez l'ID ou le lien, puis Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Ouvre les options du suivi des quêtes du Journal des donjons."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Ouvre l'éditeur d'ATH : cliquez sur un autre élément de Naowh Forever avec lequel la barre se déplacera."
L["Opens the Library Books tracker's settings."] = "Ouvre les options du suivi des livres de bibliothèque."
L["Opens the planner on its Builds tab."] = "Ouvre le planificateur sur son onglet Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Ouvre le suivi des quêtes dans le monde, sur le donjon concerné par vos quêtes."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Ouvre le suivi des quêtes quand vous entrez dans un donjon avec des quêtes pour vous."
L["Opens the quiz now, or closes it."] = "Ouvre le quiz maintenant, ou le ferme."
L["Opens the Run Timer settings."] = "Ouvre les options du chrono de passage."
L["Opens the Sleeping Bag tracker's settings."] = "Ouvre les options du suivi du sac de couchage."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Ouvre la fenêtre Poids des caractéristiques : la valeur de chaque caractéristique pour votre spécialisation, et vos meilleures améliorations selon elles."
L["Opens the window now, out of combat."] = "Ouvre la fenêtre maintenant, hors combat."
