L["Plays as your target leaves melee range."] = "Retentit quand votre cible sort de portée de mêlée."
L["Plays Drop Alert with your list's first BiS, as you set it: up for a roll, dropped, then yours."] = "Joue Alerte de butin avec le premier BiS de votre liste, tel que réglé : mis en jeu, tombé, puis à vous."
L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "Retentit une fois chaque fois que votre vie passe sous le seuil. Si le jeu cache votre vie aux addons en plein combat, il ne retentit que hors combat."
L["Plays once when your threat climbs past the threshold, and again only after it drops back below."] = "Retentit une fois quand votre menace dépasse le seuil, puis seulement après qu'elle est redescendue en dessous."
L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "Joue le ping de carte et nomme le livre dans la discussion quand vous arrivez à portée d'un livre qu'il vous faut encore. Une fois par livre, jusqu'à ce que vous vous éloigniez et reveniez."
L["Plays the map ping when a book is near."] = "Joue le ping de carte quand un livre est proche."
L["Plays the sound again this often while out of range. 0 plays it once."] = "Rejoue le son à cet intervalle tant que la cible est hors de portée. 0 le joue une fois."
L["Plays the sound picked here."] = "Joue le son choisi ici."
L["Plays when it is time to refresh the camp."] = "Retentit quand il est temps d'actualiser le camp."
L["Plays when the warning comes up, and flashes the game's icon on your taskbar."] = "Retentit quand l'avertissement apparaît, et fait clignoter l'icône du jeu dans votre barre des tâches."
