L["Puts back the last change. Ctrl + Z."] = "Annule la dernière modification. Ctrl + Z."
L["Puts both back where the game shows them."] = "Remet les deux là où le jeu les affiche."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Remet chaque poids de cette spécialisation par défaut. Demande d'abord."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Place en premier la nourriture, les boissons et les potions de 10 niveaux ou plus sous le vôtre, marquées d'une horloge."
L["Puts the bar back on the screen."] = "Remet la barre à l'écran."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Remet les boutons de la barre comme à l'origine : le Journal des donjons et Découverte à gauche, la liste BiS et le planificateur d'entraînement à droite."
L["Puts the card back above the middle of the screen, where it starts."] = "Remet la carte au-dessus du centre de l'écran, sa position de départ."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Place l'objet le moins cher au bout de la rangée au lieu d'à côté de son ancrage."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Place l'objet le moins cher sur votre curseur, pour le jeter ou le vendre."
L["Puts the count just past the icon's edge."] = "Place le nombre juste au-delà du bord de l'icône."
L["Puts the key just past the icon's edge."] = "Place la touche juste au-delà du bord de l'icône."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Place les matériaux pour ce nombre de fabrications sur votre liste d'achats : chaque composant coché que les marchands ne vendent pas, quel que soit le contenu de vos sacs. Décochez un composant pour l'omettre. À l'hôtel des ventes la liste s'affiche à côté, pour vérifier les prix et tout acheter."
L["Puts the popup back where it first showed."] = "Remet la fenêtre là où elle est apparue la première fois."
L["Puts the quiz back where it first opened."] = "Remet le quiz là où il s'est ouvert la première fois."
L["Puts the text just past the icon's edge."] = "Place le texte juste au-delà du bord de l'icône."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Ajoute cette recette à la commande de droite, avec le nombre de fabrications et les matériaux que vous apportez. Les changements faits ici après l'ajout modifient aussi la commande. Jusqu'à %d recettes par commande."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Équipe cet ensemble. En combat, il s'équipe à la fin du combat."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Applique à vos options l'une des configurations de Naowh, ou vous les présente à nouveau."
