L["Sends the crafter one message per craft: how many you want, the materials you bring and your tip. In party chat, starting with their name, when they are in your party; else as a whisper (also in a raid). The order is emptied once sent."] = "Envoie à l'artisan un message par fabrication : combien vous en voulez, les matériaux que vous apportez et votre pourboire. Dans la discussion de groupe, en commençant par son nom, s'il est dans votre groupe ; sinon en chuchotement (aussi en raid). La commande est vidée une fois envoyée."
