L["Shown while you have a bow, gun, crossbow, wand or thrown weapon."] = "Affiché quand vous avez un arc, une arme à feu, une arbalète, une baguette ou une arme de jet."
L["Shown while you have a weapon in your off hand."] = "Affiché quand vous avez une arme en main gauche."
L["Shown with threat"] = "Affiché avec de la menace"
L["Shown: click to hide it."] = "Affiché : cliquez pour le masquer."
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "Affiche les boss et le butin d'un donjon à côté de la carte du monde quand vous êtes à l'intérieur."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "Affiche l'icône d'un objet de soin dès que votre vie passe sous le seuil, en combat aussi : le jeu l'affiche et la masque lui-même. Déplacez-la dans l'éditeur d'ATH."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "Affiche l'infobulle d'un sort d'exemple avec la ligne telle que vos options la dessinent."
L["Shows a zone's level range when you hover it on the world map."] = "Affiche la tranche de niveaux d'une zone quand vous la survolez sur la carte du monde."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "Affiche une icône à l'écran quand vous connaissez Découverte d'herbes, Découverte de gisements ou Découverte de poissons sans en pister aucun. Cliquez dessus pour commencer le pistage : clic gauche pour le premier, clic droit pour le deuxième, clic milieu pour le troisième. Survolez-la pour voir lequel est lequel. Masquée en combat. Déplacez-la dans l'éditeur d'ATH."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "Affiche chaque étape du sac de couchage, avec comment atteindre la suivante et un point de passage."
L["Shows every bonus again; click one on the preview to hide it."] = "Réaffiche chaque bonus ; cliquez sur l'un dans l'aperçu pour le masquer."
L["Shows how many of each you carry."] = "Affiche combien de chacun vous portez."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "Indique si vous êtes en avance ou en retard sur vos autres personnages, et colore les niveaux passés en conséquence."
L["Shows it again a little before its effect runs out."] = "Le réaffiche peu avant la fin de son effet."
L["Shows only part of the raid."] = "Affiche seulement une partie du raid."
L["Shows or hides the list of every element."] = "Affiche ou masque la liste de tous les éléments."
L["Shows the factions earned where you are beside the world map."] = "Affiche à côté de la carte du monde les factions dont vous gagnez la réputation là où vous êtes."
L["Shows the key that uses each button."] = "Affiche la touche qui utilise chaque bouton."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "Affiche l'indicateur avec des barres d'exemple à sa place à l'écran, pendant dix secondes. Hors combat uniquement."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "Affiche les affaiblissements de l'autre tank à côté de sa barre de vie, en combat aussi : cumuls de tank-buster, affaiblissements de boss et tout ce que vous pouvez dissiper."
L["Shows the parts of the world map you have not explored yet, darkened."] = "Affiche, assombries, les parties de la carte du monde que vous n'avez pas encore explorées."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "N'affiche la rangée qu'une fois vos sacs remplis à ce point. 0 l'affiche en permanence."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "Affiche sur votre carte les étapes du sac de couchage restantes ; cliquez sur l'une pour un point de passage."
L["Shows the warning with its sound, about your target if you can attack it."] = "Affiche l'avertissement avec son son, sur votre cible si vous pouvez l'attaquer."
L["Shows this bonus on the bar: %s."] = "Affiche ce bonus sur la barre : %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "Affiche les composants de cette recette dans votre suivi des objectifs, avec combien vous en avez de chacun."
L["Shows this visit's time, coins, and experience."] = "Affiche la durée, l'argent et l'expérience de cette visite."
L["Shows up once you take the talent"] = "Apparaît une fois le talent pris"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "Montre qui sont Naowh, les développeurs, les modérateurs et nos mécènes légendaires et épiques : un badge près de leur nom dans la discussion, une ligne dans leur infobulle et, si vous le voulez, une bannière quand l'un d'eux rejoint votre groupe."
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "Montre vos étoiles BiS aux joueurs qui vous inspectent avec Naowh Forever."
L["Shows your note and tag on a player's tooltip."] = "Affiche votre note et votre étiquette dans l'infobulle d'un joueur."
L["Shows your other characters' visits."] = "Affiche les visites de vos autres personnages."
