L["The AuraBuffs window: the consumables to watch."] = "La fenêtre AuraBuffs : les consommables à surveiller."
L["The bar and the FPS / MS readout fade to Faded Opacity until you hover them. Their buttons still click while faded."] = "La barre et l'affichage IPS / MS passent à l'Opacité estompée jusqu'à ce que vous les surviliez. Leurs boutons restent cliquables quand ils sont estompés."
L["The bar as it shows outside a fight."] = "La barre telle qu'elle s'affiche hors combat."
L["The bar as it sits on your screen."] = "La barre telle qu'elle est placée à l'écran."
L["The best scores of the players you have met, in this mode."] = "Les meilleurs scores des joueurs que vous avez croisés, dans ce mode."
L["The BiS List's own window, and its Stat Weights window."] = "La fenêtre propre de la liste BiS, et sa fenêtre Poids des caractéristiques."
L["The BiS rankings behind the BiS List."] = "Les classements BiS derrière la liste BiS."
L["The book count is what players report; not confirmed yet."] = "Le nombre de livres provient des signalements des joueurs ; pas encore confirmé."
L["The boss or place it comes from."] = "Le boss ou le lieu d'où il provient."
L["The buffs show while you hover the icon."] = "Les améliorations s'affichent au survol de l'icône."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "Le talent suivant du build ne peut pas être pris maintenant : vos talents ne sont pas ceux du build."
L["The calendar cannot be opened from the Top Bar with a gamepad."] = "Le calendrier ne peut pas être ouvert depuis la barre du haut avec une manette."
L["The card at the end of a round."] = "La carte à la fin d'une manche."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Les objets les moins chers de vos sacs en rangée d'icônes, le moins cher d'abord. Ctrl-clic sur une icône pour le détruire, ou cliquez pour le vendre quand un marchand est ouvert. Clic milieu pour ignorer un objet. Déplacez-la dans l'éditeur d'ATH."
L["The class's name, or its class icon, which fits however small the buttons are."] = "Le nom de la classe, ou son icône de classe, qui tient quelle que soit la petitesse des boutons."
L["The color of the line on the tooltip."] = "La couleur de la ligne dans l'infobulle."
L["The Consumable Bar will ask about those items again."] = "La barre de consommables redemandera pour ces objets."
L["The consumables your reminders watch"] = "Les consommables surveillés par vos rappels"
L["The consumables your reminders watch."] = "Les consommables surveillés par vos rappels."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "La chaîne de quêtes cachée du Sac de couchage douillet, étape par étape."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "Les contrôles de foule sur votre cible ; choisissez lesquels dans la carte Contrôle de foule ci-dessous."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "La ligne Ctrl-clic, et Cliquer pour vendre quand un marchand est ouvert."
L["The cursor left still."] = "Le curseur laissé immobile."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "Les affaiblissements sur votre cible choisis dans la carte Affaiblissements ci-dessous, comme Frappe mortelle."
L["The default is %s."] = "La valeur par défaut est %s."
L["The default is %s. Click to put it back."] = "La valeur par défaut est %s. Cliquez pour la rétablir."
L["The Disenchant window cannot open in combat."] = "La fenêtre de désenchantement ne peut pas s'ouvrir en combat."
L["The Dungeon Quest Tracker's window."] = "La fenêtre du suivi des quêtes de donjon."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "Le territoire dont la liste affiche les donjons. Les donjons contestés et les raids sont toujours listés. Également l'interrupteur à côté de la recherche du Journal."
L["The Edit Items window."] = "La fenêtre Modifier les objets."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "L'écart supplémentaire entre votre aura et Fureur vertueuse et les boutons de classe."
L["The fastest way to any waypoint."] = "Le chemin le plus rapide vers n'importe quel point de passage."
L["The first %d of %d; type more to narrow it down."] = "Les %d premiers sur %d ; tapez davantage pour affiner."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "La première fois que quelqu'un parle, demande sa zone à son Naowh Forever via un chuchotement d'addon caché. Les joueurs sans l'addon ne voient jamais la question."
L["The flight time to each destination when you hover it on the flight master's map."] = "La durée du vol vers chaque destination quand vous la survolez sur la carte du maître de vol."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "La police des nombres de dégâts et de soins, au-dessus des ennemis et de votre personnage. Désactivé, la police du jeu reste inchangée."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "La police du reste du jeu : menus, discussion, infobulles et noms. Désactivé, les polices du jeu restent inchangées."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "La police des fenêtres et de l'ATH de cet addon. Les options de police d'une fonction l'utilisent sauf si elles en choisissent une autre. Enregistré pour cet ordinateur.|n|nPrend effet après un /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "L'affichage IPS / MS et les compteurs en ligne sur les boutons."
L["The FPS / MS readout stays up."] = "L'affichage IPS / MS reste visible."
L["The game does not name this fight yet: its kills count once the raid opens."] = "Le jeu ne nomme pas encore ce combat : ses victoires seront comptées à l'ouverture du raid."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "Le jeu n'a pas encore de rang JcJ pour vous. Il s'affiche une fois la saison commencée."
L["The game has no route for %s, and its quest giver's spot is not known."] = "Le jeu n'a pas d'itinéraire pour %s, et l'emplacement de son donneur de quêtes est inconnu."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "Le jeu ne transmet pas les messages d'addon pour l'instant (rencontre en cours) : redemandez après."
L["The game lists no rank rewards for this season yet."] = "Le jeu ne liste pas encore de récompenses de rang pour cette saison."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "Le jeu a refusé de désenchanter ceci (compétence trop basse ?). Ignoré jusqu'au rechargement."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Les sons d'alerte du jeu d'abord, puis ceux de l'addon. Chacun est joué quand vous le choisissez."
L["The game's own look, in gold and bronze."] = "Le style propre au jeu, en or et bronze."
L["The gap between the two."] = "L'écart entre les deux."
L["The gap between two buttons."] = "L'écart entre deux boutons."
L["The Gear Sets window, with every set and what you can do with it."] = "La fenêtre des ensembles d'équipement, avec chaque ensemble et ce que vous pouvez en faire."
L["The group can be disbanded once the fight is over."] = "Le groupe peut être dissous une fois le combat terminé."
L["The group's paladins and the blessing each gives every class."] = "Les paladins du groupe et la bénédiction que chacun donne à chaque classe."
L["The guild name under a player's name."] = "Le nom de guilde sous le nom d'un joueur."
L["The highest rank this season"] = "Le rang le plus élevé de cette saison"
L["The icon grows and shrinks with it."] = "L'icône grandit et rétrécit avec."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "La fenêtre d'inspection au style de la liste BiS, avec leur score, la vérification d'équipement, les talents et l'historique."
L["The item's cooldown sweeps over its icon."] = "Le temps de recharge de l'objet balaye son icône."
L["The item's quality"] = "La qualité de l'objet"
L["The item, your star and what happened, on screen for a while."] = "L'objet, votre étoile et ce qui s'est passé, à l'écran pendant un moment."
L["The items the Buffs & Consumables reminders watch."] = "Les objets surveillés par les rappels d'améliorations et consommables."
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "Le Journal à côté de la carte du monde : boss et butin en donjon, factions à l'extérieur."
L["The Journal's own window."] = "La fenêtre propre du Journal."
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "La touche qui modifie Accepter les quêtes, Rendre les quêtes, Choisir les quêtes chez les PNJ et le partage."
L["The key that changes Auto Gossip for that NPC."] = "La touche qui modifie le dialogue automatique pour ce PNJ."
L["The key that opens the BiS List."] = "La touche qui ouvre la liste BiS."
L["The key that opens the Journal."] = "La touche qui ouvre le Journal."
L["The key that opens the Quest List window."] = "La touche qui ouvre la fenêtre Liste des quêtes."
L["The last %ds, scrolling %s%s"] = "Les %d dernières s, défilement %s%s"
L["The last fight's time stays on screen until the next one starts."] = "La durée du dernier combat reste à l'écran jusqu'au début du suivant."
L["The last part of each melee swing, shaded."] = "La dernière partie de chaque coup de mêlée, ombrée."
L["the last profile cannot be deleted"] = "le dernier profil ne peut pas être supprimé"
L["The last profile cannot be deleted."] = "Le dernier profil ne peut pas être supprimé."
L["The latest %d kills. First counted: %s."] = "Les %d dernières victoires. Première comptée : %s."
L["The latest %d. First counted: %s."] = "Les %d derniers. Premier compté : %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "La zone du chef sur chaque annonce de la recherche de groupe, et la zone de chaque membre au survol."
L["The level you are on as it runs, then completed levels, newest first."] = "Le niveau en cours pendant qu'il avance, puis les niveaux terminés, le plus récent d'abord."
L["The line round the bar."] = "La ligne autour de la barre."
L["The list this character uses."] = "La liste que ce personnage utilise."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "La durée maximale d'une amélioration pour qu'elle s'affiche ; les plus longues comme Intelligence des Arcanes restent masquées."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "Les macros que l'addon écrit et tient à jour pour vous, hors combat. Activez-en une ici, ou placez-la sur vos barres depuis Macros intelligentes dans Naowh's Forge."
L["The macros you saved to the Forge's Library."] = "Les macros que vous avez enregistrées dans la bibliothèque de la Forge."
L["The Man. The King."] = "L'homme. Le roi."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "La fenêtre de la carte, le Journal à côté de la carte du monde et Butin des boss au curseur."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "Les marques sur la fenêtre du personnage du jeu, telle qu'elle est (ou celle d'EllesmereUI), sans la fenêtre du personnage Naowh. Avec celle-ci activée, ses emplacements les ont déjà."
L["The Middle-click line."] = "La ligne Clic milieu."
L["The most recent completed levels."] = "Les niveaux terminés les plus récents."
L["the name is empty"] = "le nom est vide"
L["The name on it, and the community it is made for."] = "Le nom qui y figure, et la communauté pour laquelle il est fait."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "Le bouton Naowh Forever sur la minicarte. L'entrée du compartiment des addons et /naowh ouvrent cette fenêtre dans tous les cas."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "Le N de Naowh Forever à côté du nom de Naowh, des développeurs, des modérateurs et de nos mécènes légendaires et épiques dans la discussion."
L["The newest line stays at the anchor; older lines stack in this direction."] = "La ligne la plus récente reste à l'ancrage ; les plus anciennes s'empilent dans cette direction."
L["The next one frees in "] = "La prochaine se libère dans "
L["the next rank of %s (cap %d)"] = "le rang suivant de %s (max %d)"
L["The number on each icon counts your bank as well as your bags."] = "Le nombre sur chaque icône compte votre banque en plus de vos sacs."
L["The order the points are taken in"] = "L'ordre dans lequel les points sont pris"
L["the pattern"] = "le patron"
L["The people and projects behind Naowh Forever."] = "Les personnes et projets derrière Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "Le butin et les techniques du boss choisi, sous la carte."
L["The planner's own window, and a mini bar to leave up while you level."] = "La fenêtre propre du planificateur, et une mini-barre à laisser affichée pendant la progression."
L["The player list opens after combat."] = "La liste des joueurs s'ouvre après le combat."
L["The player's guild rank beside their guild name."] = "Le rang de guilde du joueur à côté de son nom de guilde."
L["The point of the bar that attaches."] = "Le point de la barre qui s'attache."
L["The point of the frame it attaches to."] = "Le point du cadre auquel elle s'attache."
L["The purchase failed."] = "L'achat a échoué."
L["The purchase failed; the price may have changed."] = "L'achat a échoué ; le prix a peut-être changé."
L["The purchase failed; the price may have changed.|r"] = "L'achat a échoué ; le prix a peut-être changé.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "Le suivi des quêtes, et le partage des quêtes de donjon avec votre groupe."
L["The quests that reward a pick you do not have yet."] = "Les quêtes qui récompensent avec un choix que vous n'avez pas encore."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "Le quiz s'ouvre quand vous vous asseyez à un feu de camp et se ferme quand vous vous levez."
L["The raid marker Mark Focus puts on your focus."] = "Le marqueur de raid que Marquer la focalisation place sur votre focalisation."
L["the rank before"] = "le rang précédent"
L["The ready ring shows with GCD Sweep on."] = "L'anneau prêt s'affiche avec Balayage du GCD activé."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "Les composants utilisés par vos sorts connus, comme la Poudre des arcanes, les bougies, les graines, les Symboles des rois et la Poudre éclipsante, selon le plus haut rang que vous connaissez."
L["The red time left blinks, to catch your eye."] = "Le temps restant en rouge clignote, pour attirer l'œil."
L["The same required-level filter applies to every stack, not each item separately."] = "Le même filtre de niveau requis s'applique à chaque pile, et non à chaque objet séparément."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Les mêmes ensembles que dans la fiche du personnage : équipez-les, enregistrez-les, renommez-les ou supprimez-les dans la fenêtre des ensembles d'équipement."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "La même chose avec une bénédiction supérieure, pour une classe qui partage une bénédiction, quand vous portez des Symboles des rois."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "Les secondes restantes à partir desquelles le temps devient rouge ; il devient jaune au double."
L["The serializer libraries are missing from this build."] = "Les bibliothèques de sérialisation manquent dans cette version."
L["The shape of Naowh's arrow."] = "La forme de la flèche de Naowh."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "La part du prix de vente des objets que le pourboire suggéré ajoute au remboursement des matériaux de l'artisan. Au moins 1 pa sauf si réglé à 0."
L["The shortest time between two thanks to the same player."] = "Le délai minimum entre deux remerciements au même joueur."
L["The Slot"] = "L'emplacement"
L["The slot it is for."] = "L'emplacement concerné."
L["The slots and stats only"] = "Les emplacements et caractéristiques uniquement"
L["The space between Naowh's arrow and the text under it."] = "L'espace entre la flèche de Naowh et le texte en dessous."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "La spécialisation pour laquelle votre équipement est évalué. Automatique suit vos talents : l'arbre avec le plus de points (le Combat farouche d'un druide est évalué pour les dégâts ; choisissez Feral Tank pour un ours)."
L["The spot ahead of you, 312 yards away."] = "L'endroit devant vous, à 312 m."
L["The spot off to your right."] = "L'endroit sur votre droite."
L["The stat weights each spec starts with."] = "Les poids de caractéristiques de départ de chaque spécialisation."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "Le texte de camouflage quand vous êtes camouflé, en plus du rappel quand vous ne l'êtes pas."
L["The step and distance text under RestedXP's waypoint arrow."] = "Le texte d'étape et de distance sous la flèche de point de passage de RestedXP."
L["The string is damaged: copy it again in full."] = "La chaîne est endommagée : copiez-la à nouveau en entier."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "Le pourboire suggéré rembourse les matériaux de l'artisan plus %d%% du prix de vente des objets (de tous les matériaux, pour une recette qui ne crée pas d'objet), arrondi, au moins 1 pa. Fixez votre propre pourboire dans la liste de commande à droite. Changez la part dans les options de Métiers."
L["The swing timer needs WoW: Forever's own swing event."] = "Le minuteur de coups nécessite l'événement de coup propre à WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "L'étiquette dans la couleur de classe de l'auteur. Désactivé, elle est grise."
L["the talent above it"] = "le talent au-dessus"
L["The talent builds you saved in the Training Planner."] = "Les builds de talents enregistrés dans le planificateur d'entraînement."
L["The Team"] = "L'équipe"
L["The text in the theme's accent color instead of gold."] = "Le texte dans la couleur d'accent du thème au lieu de l'or."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "Le thème qu'utilise RestedXP : le sien, ou l'un des thèmes Naowh."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "L'heure entre les deux côtés. Cliquez dessus pour le calendrier (pas avec une manette)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "Le temps restant devient jaune, puis rouge vers la fin, pour voir quand un contrôle de foule va se rompre."
L["The time left, turning yellow, then red, as the camp runs down."] = "Le temps restant, qui passe au jaune puis au rouge à mesure que le camp s'épuise."
L["The tint on every button's icon: Naowh's own and any addon's."] = "La teinte de l'icône de chaque bouton : ceux de Naowh et ceux de tout addon."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "L'aide du planificateur d'entraînement pendant la progression : une notification quand vous montez de niveau avec des sorts à apprendre, et un panneau à côté de votre entraîneur de classe."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "Le cadre d'unité auquel la barre est attachée, ou UIParent pour l'écran."
L["The weights"] = "Les poids"
L["The weights for %s."] = "Les poids pour %s."
L["The window's border fades with it."] = "La bordure de la fenêtre s'estompe avec elle."
L["The word itself."] = "Le mot lui-même."
L["The XP of completed quests, and their text."] = "L'XP des quêtes terminées, et son texte."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "L'XP des quêtes encore en cours, en segment estompé après celles terminées."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "L'XP des quêtes encore en cours. Par défaut la couleur des quêtes terminées, estompée."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "La zone de quiconque parle dans un canal de discussion, la discussion de guilde ou un chuchotement, devant son message. Le jeu ne dit jamais où se trouve un inconnu, un joueur est donc étiqueté une fois qu'il est dans la recherche de groupe, votre guilde, vos amis ou votre groupe, est apparu dans un /who, ou a répondu depuis sa propre copie de Naowh Forever. Son premier message peut arriver sans étiquette."
L["Their BiS"] = "Leur BiS"
L["THEIR GEAR"] = "LEUR ÉQUIPEMENT"
L["Their gear, talents and history"] = "Leur équipement, leurs talents et leur historique"
L["their materials + %d%%"] = "leurs matériaux + %d%%"
L["Their materials:"] = "Leurs matériaux :"
L["Their Naowh Score at the top of the panel, with yours under it."] = "Leur Naowh Score en haut du panneau, avec le vôtre en dessous."
L["Their supporter badge in the window's corner, if they have one."] = "Leur badge de soutien dans le coin de la fenêtre, s'ils en ont un."
L["Thelsamar"] = "Thelsamar"
L["Them"] = "Eux"
L["them all."] = "tous."
L["Theme"] = "Thème"
L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "Thèmes prédéfinis pour les fenêtres et les cadres d'ATH de l'addon, plus une option Personnalisé pour vos propres couleurs. Si le texte devient difficile à lire, choisissez Naowh (par défaut). Enregistré pour cet ordinateur.|n|nPrend effet après un /reload."
L["then"] = "puis"
L["then "] = "puis "
