L["This character last used %s. Import any set from the window, out of combat."] = "Ce personnage a utilisé %s en dernier. Importez n'importe quelle configuration depuis la fenêtre, hors combat."
L["This character's latest kills and loot."] = "Les dernières victoires et le dernier butin de ce personnage."
L["This character's macros"] = "Macros de ce personnage"
L["This client has no swing event"] = "Ce client n'a pas d'événement de coup"
