L["This is a new adventure for all of us. Naowh Forever is crafted by a small, dedicated team with a lot of passion, and we hope you enjoy every bit of it."] = "C'est une nouvelle aventure pour nous tous. Naowh Forever est conçu par une petite équipe dévouée et passionnée, et nous espérons que vous en apprécierez chaque détail."
L["This is a talent build. It is added to your builds in the Training Planner."] = "C'est un build de talents. Il est ajouté à vos builds dans le planificateur d'entraînement."
