L["Threat on your target or focus for everyone in your group, one bar each. A friendly target shows the enemy it is fighting. Scroll the meter for more entries; unlock its window to drag and resize it, or place it in the HUD Editor."] = "La menace sur votre cible ou focalisation pour chaque membre du groupe, une barre chacun. Une cible alliée affiche l'ennemi qu'elle combat. Faites défiler l'indicateur pour plus d'entrées ; déverrouillez sa fenêtre pour la déplacer et la redimensionner, ou placez-la dans l'éditeur d'ATH."
