L["What a point of each stat is worth to your spec."] = "Ce que vaut un point de chaque caractéristique pour votre spécialisation."
L["What a saved set brings back when you import it. Sets are saved and imported from the Action Bars window, out of combat."] = "Ce qu'une configuration enregistrée rétablit quand vous l'importez. Les configurations s'enregistrent et s'importent depuis la fenêtre Barres d'action, hors combat."
L["What a waypoint from the Discovery window or the tracker does."] = "Ce que fait un point de passage depuis la fenêtre Découverte ou le suivi."
L["What a zone's page in the Quest List window lists."] = "Ce que liste la page d'une zone dans la fenêtre Liste des quêtes."
L["What a zone's page in the Quest List window lists. Kills count from when Discovery is on: Shift-click a rare there to tick off one you killed before."] = "Ce que liste la page d'une zone dans la fenêtre Liste des quêtes. Les victoires sont comptées depuis l'activation de Découverte : Maj-cliquez sur un rare pour cocher celui que vous avez tué avant."
L["What changed in recent builds."] = "Ce qui a changé dans les builds récents."
L["WHAT COMES ACROSS"] = "CE QUI EST TRANSFÉRÉ"
L["What drops in every dungeon and raid."] = "Ce qui tombe dans chaque donjon et raid."
L["What each line is worth, in gold, silver and copper."] = "Ce que vaut chaque ligne, en or, argent et cuivre."
L["What each stack is worth, in its largest coin, under its icon."] = "Ce que vaut chaque pile, dans sa plus grosse pièce, sous son icône."
L["What each stat is worth to your spec: change them as you like."] = "Ce que vaut chaque caractéristique pour votre spécialisation : modifiez-les à votre guise."
L["What each stat is worth to your spec: the BiS List's upgrade percents and enchants come from them. Change the weights in the Stat Weights window, from the scales on the BiS List's title bar."] = "Ce que vaut chaque caractéristique pour votre spécialisation : les pourcentages d'amélioration et les enchantements de la liste BiS en découlent. Modifiez les poids dans la fenêtre Poids des caractéristiques, via la balance de la barre de titre de la liste BiS."
L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "Ce que vaut chaque caractéristique pour votre spécialisation : les pourcentages d'amélioration et les enchantements en découlent. Fixez les vôtres."
L["What Happened"] = "Ce qui s'est passé"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "Ce qui se passe quand vous ouvrez un marchand. Les deux fonctionnent que le rappel de réapprovisionnement soit activé ou non."
L["What It Lists"] = "Ce qui est listé"
L["What it lists"] = "Ce qui est listé"
L["What it puts on you: a buff, or an enchant on a weapon."] = "Ce qu'il vous applique : une amélioration, ou un enchantement sur une arme."
L["What it says while you are in stealth."] = "Ce qui s'affiche quand vous êtes camouflé."
L["What it says while you are out of stealth."] = "Ce qui s'affiche quand vous n'êtes pas camouflé."
L["What it shows as you enter combat."] = "Ce qui s'affiche à l'entrée en combat."
L["What it shows as you leave combat."] = "Ce qui s'affiche à la sortie du combat."
L["What Lines Show"] = "Contenu des lignes"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Ce que la fenêtre de métier de Naowh ajoute à chaque recette : celles pas encore apprises, votre rang suivant, et combien vous avez de chaque composant."
L["What opens when a flight starts; Off hides the Games button."] = "Ce qui s'ouvre au début d'un vol ; Désactivé masque le bouton Jeux."
L["What Rows Show"] = "Contenu des lignes"
L["What shows while you know a find but track none."] = "Ce qui s'affiche quand vous connaissez une découverte sans en pister aucune."
L["What the copy card has selected when it opens."] = "Ce que la carte de copie sélectionne à son ouverture."
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "Ce que le Journal liste pour un boss. Les mêmes interrupteurs que l'icône Filtres de sa barre de titre."
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "Ce que rapporte la pile à l'hôtel des ventes, d'après votre dernière analyse des prix ou TradeSkillMaster."
L["What the whole stack sells for at a vendor, and each item's price."] = "Ce que rapporte toute la pile chez un marchand, et le prix de chaque objet."
L["What to train at each level, and its cost."] = "Ce qu'il faut apprendre à chaque niveau, et son coût."
L["What you can train now and what each level brings."] = "Ce que vous pouvez apprendre maintenant et ce qu'apporte chaque niveau."
L["What you can train now, what each level brings and what it costs."] = "Ce que vous pouvez apprendre maintenant, ce qu'apporte chaque niveau et ce que ça coûte."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "Ce que vous payez à l'artisan pour cette fabrication, envoyé avec le chuchotement. Prérempli avec le pourboire suggéré ; tapez le vôtre sous la forme 2g 50s, 75s ou 2.5 (or). Videz-le pour revenir à la suggestion."
L["What you wear that takes a better enchant for your level."] = "Ce que vous portez qui accepte un meilleur enchantement pour votre niveau."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "Ce que fait votre cible en combat : ses améliorations courtes et les contrôles de foule sur elle."
L["Wheel"] = "Molette"
L["Wheel on the rows"] = "Molette sur les lignes"
L["Wheel: size. Right-click for more."] = "Molette : taille. Clic droit pour plus."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "Molette : taille du texte. Cliquez sur une ligne pour la masquer. Clic droit pour plus."
L["When"] = "Quand"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "Quand la compétence d'un métier est assez haute pour son rang suivant (Compagnon, Expert, Artisan), une bannière sous la barre de compétence et sur sa carte dans la vue d'ensemble indique ce qu'il faut et qui l'enseigne : l'entraîneur, le vendeur de livres ou le donneur de quêtes le plus proche. Cliquez sur Point de passage pour les marquer sur votre carte. L'atteindre l'indique aussi une fois dans la discussion ; /naowh profrank le répète."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "Quand un objet de votre liste est mis en jeu ou dans la fenêtre de butin, et à nouveau quand il est à vous. Déplacez l'alerte à l'écran dans l'éditeur d'ATH."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "Quand un PNJ propose plusieurs choses, va directement à une quête terminée à rendre, ou à la première quête proposée. Fonctionne avec les deux options ci-dessus."
L["When it is up for a roll or drops."] = "Quand il est mis en jeu ou qu'il tombe."
L["When it is yours."] = "Quand il est à vous."
L["When You Leave"] = "En partant"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "Quand vous montez de niveau avec de nouveaux sorts à apprendre, une notification indique combien et leur coût, avec des boutons pour ouvrir le planificateur et placer un point de passage vers l'entraîneur le plus proche. Déplacez-la dans l'éditeur d'ATH."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "À la déconnexion, la configuration enregistrée en dernier par ce personnage est réenregistrée avec vos barres, macros et raccourcis tels qu'ils sont."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "Quand vous arrivez en ville ou dans une auberge, une liste clignotante au centre de l'écran de ce qui vous manque. Elle reste jusqu'à ce que vous ayez le nécessaire ou partiez. Déplacez-la dans l'éditeur d'ATH."
L["When You Reset"] = "À la réinitialisation"
L["Where"] = "Où"
L["Where %s starts is not known."] = "Le point de départ de %s est inconnu."
L["Where do you want to start?"] = "Par où voulez-vous commencer ?"
L["Where it comes from is not recorded yet; try the Auction House."] = "Sa provenance n'est pas encore enregistrée ; essayez l'hôtel des ventes."
L["Where It Drops"] = "Provenance"
L["Where on the frame the bar sits."] = "L'endroit du cadre où se place la barre."
L["Where to get them"] = "Où les obtenir"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "Où se placent votre écart avant la prise d'aggro et le nombre d'entrées : sous les barres, ou entre la barre de titre et les barres."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "Où se place votre étoile : au coin de l'icône, avant le nom, ou masquée."
L["Where? on Whispers"] = "Où ? sur les chuchotements"
L["Whether a healthstone or a potion comes first."] = "Si une pierre de soins ou une potion passe en premier."
L["Whether a new mark counts on every character or only this one."] = "Si une nouvelle marque compte sur tous les personnages ou seulement sur celui-ci."
L["Whether NF Food leaves drinks to NF Drink."] = "Si NF Food laisse les boissons à NF Drink."
L["Which blessing you give this class: Might, Wisdom, Kings, Salvation or Light."] = "Quelle bénédiction vous donnez à cette classe : Puissance, Sagesse, Rois, Salut ou Lumière."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "Quels contrôles de foule s'affichent, par technique : chaque rang, et le même sort venant d'objets et de créatures."
L["Which debuffs show beside crowd control: off until you light them."] = "Quels affaiblissements s'affichent à côté des contrôles de foule : désactivés jusqu'à ce que vous les éclairiez."
L["Which guild and title lines show with players' names, saved by the game itself."] = "Quelles lignes de guilde et de titre s'affichent avec les noms des joueurs, enregistré par le jeu lui-même."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "Quels types de consommables Analyser les sacs ajoute et sur lesquels Demander l'ajout pose la question."
L["Which mana spells get the line."] = "Quels sorts à mana reçoivent la ligne."
L["Which modules do you want?"] = "Quels modules voulez-vous ?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "Lesquels de vos choix déclenchent une alerte : votre BiS seul, vos deux premiers, ou chaque choix de votre liste."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "Ce que la macro utilise d'abord quand vous portez les deux : une pierre de soins ou une potion de soins."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "Quand un marchand est ouvert, un bouton Acheter sous les composants de la recette choisie lui achète, en un clic, chaque composant coché qu'il vend, comme le Fil grossier ou le Flux faible, pour autant de fabrications que réglé à côté. Le coût total s'affiche à côté du bouton ; survolez Acheter pour chaque composant."
L["While flying"] = "En vol"
L["While flying and at the campfire"] = "En vol et au feu de camp"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "Quand Frappe héroïque, Enchaînement, Mutiler ou Attaque du raptor est en attente, les barres de mêlée prennent sa couleur et son nom."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "Quand l'hôtel des ventes est ouvert, un bouton Acheter sous les composants de la recette choisie achète les matériaux pour autant de fabrications que réglé à côté : chaque composant coché que les marchands ne vendent pas. Chacun affiche d'abord son prix et n'est acheté que lorsque vous cliquez sur Confirmer."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "Quand l'hôtel des ventes est ouvert, un bouton Rechercher à l'HV à côté du nom de la recette choisie y recherche l'objet qu'elle fabrique. Les recettes non apprises ont aussi Rechercher une recette, pour le patron, les plans ou le manuel qui l'enseigne. Les recettes qui ne fabriquent pas d'objet, comme les enchantements, n'ont pas Rechercher à l'HV."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "Quand l'hôtel des ventes est ouvert, Maj-cliquez sur une recette ou un composant pour rechercher l'objet à l'hôtel des ventes : ce que fabrique la recette, ou le composant. Pendant que vous tapez dans la discussion, Maj-clic le lie toujours."
L["While the mouse is away, with Show On Mouseover on."] = "Quand la souris est ailleurs, avec Afficher au survol activé."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "En groupe, partage avec les autres chaque quête acceptée d'un PNJ, si elle peut être partagée. Une quête que quelqu'un a partagée avec vous n'est pas repartagée. Le modificateur maintenu à l'acceptation la garde pour vous."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "Quand vous portez des livres, un marqueur sur celui qui les prend : votre bibliothécaire, ou l'entraîneur de mage."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "Pendant une incantation, marque où elle se termine sur la barre de main droite. Le repère devient rouge si l'incantation sera encore en cours quand le coup arrive."
