L["Whoever holds aggro in one color."] = "Celui qui a l'aggro dans une couleur."
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "Le classement affiché par le sélecteur. Chaque spécialisation garde ses propres choix sur une liste."
L["Wide kite"] = "Cerf-volant large"
L["Widen the swing and Auto Shot windows by your world latency, so they show when to press rather than when the server acts."] = "Élargit les fenêtres de coup et de Tir automatique selon votre latence monde, pour qu'elles indiquent quand appuyer plutôt que quand le serveur agit."
