L["Your BiS"] = "Votre BiS"
L["your BiS"] = "votre BiS"
L["Your BiS in your bags or bank: put it on."] = "Votre BiS dans vos sacs ou en banque : équipez-le."
L["Your BiS list is empty"] = "Votre liste BiS est vide"
L["Your BiS list now keeps a ranked list per slot. These did not fit: "] = "Votre liste BiS garde maintenant un classement par emplacement. Ceux-ci n'ont pas pu y entrer : "
L["Your BiS List's slot marks on the items in your bags: item level, your BiS's star, Forever's mark and the green arrow on an upgrade. In the game's bags or EllesmereUI's."] = "Les marques d'emplacement de votre liste BiS sur les objets de vos sacs : niveau d'objet, étoile de votre BiS, marque Forever et flèche verte sur une amélioration. Dans les sacs du jeu ou ceux d'EllesmereUI."
L["Your BiS lists, for every class."] = "Vos listes BiS, pour chaque classe."
L["Your BiS only"] = "Votre BiS uniquement"
L["Your BiS you do not have yet: where to go next."] = "Votre BiS que vous n'avez pas encore : où aller ensuite."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "L'étoile de votre BiS sur un emplacement, et la marque Forever sur ce qui est nouveau dans Forever."
L["Your BiS, your second pick, and so on."] = "Votre BiS, votre deuxième choix, et ainsi de suite."
L["Your buttons and a clock along the top."] = "Vos boutons et une horloge en haut de l'écran."
L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "Vos boutons de part et d'autre d'une horloge facultative, avec IPS et latence en dessous."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "Vos boutons de part et d'autre d'une horloge facultative, avec IPS et latence en dessous. Disposez les boutons dans l'aperçu : faites-en glisser un pour le déplacer, son x le retire, le + d'un côté en ajoute un. Déplacez la barre dans l'éditeur d'ATH."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "Les bonus et le temps restant de votre camp à l'écran, et un rappel quand les Avantages du camp expirent."
L["Your camp's bonuses by the icon, always or while you hover it."] = "Les bonus de votre camp près de l'icône, en permanence ou au survol."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Votre plafond est %d.\nFaites d'abord la quête %s%s|r (%scompétence %d) :"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "Votre plafond est %d.\nLisez d'abord %s (compétence %d requise) :"
L["Your cap is %d.\nFirst train %s (%s, needs skill %d):"] = "Votre plafond est %d.\nApprenez d'abord %s (%s, compétence %d requise) :"
L["Your cast ends before the swing comes due."] = "Votre incantation se termine avant que le coup arrive."
L["Your cast will still be going as the swing comes due."] = "Votre incantation sera encore en cours quand le coup arrivera."
L["Your casts and channels swept around the ring too."] = "Vos incantations et canalisations balayent aussi l'anneau."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Votre fenêtre de personnage (C) au style de la liste BiS : chaque emplacement avec ses marques, vos caractéristiques pour votre spécialisation, et votre Naowh Score sous votre niveau. Le jeu garde la fenêtre et tout ce qu'elle fait. Avec EllesmereUI, activer ceci désactive sa fenêtre de personnage, et le désactiver la réactive, après un rechargement."
