L["your debuffs"] = "vos affaiblissements"
L["Your equipment sets, the same ones the character sheet keeps."] = "Vos ensembles d'équipement, les mêmes que ceux de la fiche du personnage."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "Votre expérience par heure sur une petite carte, avec le temps avant le niveau, le temps de jeu, la durée de la session et les temps des derniers niveaux. Masquée au niveau maximum. Survolez-la pour Démarrer, Pause et Réinitialiser (aussi /naowh xp start, pause ou reset). Déplacez-la dans l'éditeur d'ATH."
L["Your experience. Its left end is a darker shade."] = "Votre expérience. Son extrémité gauche est d'une teinte plus foncée."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Votre vol sur une carte : temps restant, les arrêts sur un tracé, et le prochain arrêt."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "Les incantations de votre cible focalisée sur une barre dédiée, colorée selon que votre interruption est prête, avec un repère là où elle sort de recharge et un bouclier sur les incantations que vous ne pouvez pas interrompre. Votre interruption est la première que vous connaissez parmi Volée de coups, Coup de bouclier, Coup de pied, Contresort, Horion de terre, Silence et Charge farouche. Déplacez-la dans l'éditeur d'ATH."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "Le nom de votre focalisation, teinté selon la classe, avec son icône de classe au-dessus du panneau."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Votre focalisation, définie avec NF Focus : ses minuteurs continuent pendant que vous combattez quelqu'un d'autre."
L["Your game macros, not the Smart Macros, as one string to share."] = "Vos macros du jeu, pas les macros intelligentes, en une chaîne à partager."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Votre temps de recharge global balayé autour de l'anneau, et un anneau prêt une fois terminé."
L["YOUR GOLD"] = "VOTRE OR"
L["Your group in range: who is missing a blessing, who is running out, and who only needs their own."] = "Votre groupe à portée : à qui il manque une bénédiction, qui l'a bientôt expirée, et qui n'a besoin que de la sienne."
L["Your group on a boss you are tanking."] = "Votre groupe sur un boss que vous tankez."
L["Your group's bars, with sample members."] = "Les barres de votre groupe, avec des membres d'exemple."
L["Your group's gear, talents and Naowh Score."] = "L'équipement, les talents et le Naowh Score de votre groupe."
L["Your group's healers and their mana, lowest first."] = "Les soigneurs de votre groupe et leur mana, le plus bas d'abord."
L["Your group's Naowh Score, gear, talents and stats."] = "Le Naowh Score, l'équipement, les talents et les caractéristiques de votre groupe."
L["Your group's threat on your target."] = "La menace de votre groupe sur votre cible."
L["Your healers' mana, with sample healers."] = "Le mana de vos soigneurs, avec des soigneurs d'exemple."
L["Your health under the threshold, with a healing item in your bags."] = "Votre vie sous le seuil, avec un objet de soin dans vos sacs."
L["Your health under the threshold, with nothing to drink or eat."] = "Votre vie sous le seuil, sans rien à boire ni à manger."
L["Your keys stay as they are."] = "Vos touches restent telles quelles."
L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "Votre niveau, votre expérience et son pourcentage sur une barre, avec l'XP des quêtes terminées et l'expérience de repos dessinées au-delà du remplissage. Remplace la barre d'expérience de Blizzard quand elle est activée. Déplacez-la dans l'éditeur d'ATH. Ctrl + clic droit sur la barre pour réinitialiser la durée de session et l'XP par heure."
L["Your List"] = "Votre liste"
L["Your list's marks on items out in the game."] = "Les marques de votre liste sur les objets dans le jeu."
L["Your list's rank on the items in it."] = "Le rang de votre liste sur les objets qu'elle contient."
L["Your list: %s%s"] = "Votre liste : %s%s"
L["Your macros"] = "Vos macros"
L["Your macros are never changed or copied twice."] = "Vos macros ne sont jamais modifiées ni copiées deux fois."
L["Your macros, checked and kept current."] = "Vos macros, vérifiées et tenues à jour."
L["Your Materials"] = "Vos matériaux"
L["Your materials"] = "Vos matériaux"
L["Your Naowh Score, big under your level: hover it for your score with your BiS and the best in the game, click it for the BiS List."] = "Votre Naowh Score, en grand sous votre niveau : survolez-le pour votre score avec votre BiS et le meilleur du jeu, cliquez dessus pour la liste BiS."
L["Your note on %s"] = "Votre note sur %s"
L["Your Own"] = "Personnalisé"
L["Your own bar among the group's."] = "Votre propre barre parmi celles du groupe."
L["Your own bar in one color instead of your class color."] = "Votre propre barre dans une seule couleur au lieu de votre couleur de classe."
L["Your own mana among the healers'."] = "Votre propre mana parmi celui des soigneurs."
L["Your party"] = "Votre groupe"
L["Your picks"] = "Vos choix"
