L["Your played time when you reached each level, beside how long it took."] = "Votre temps de jeu à chaque niveau atteint, à côté du temps qu'il a fallu."
L["Your profile has no class macros for your %s."] = "Votre profil n'a aucune macro de classe pour votre %s."
L["Your PvP Rank"] = "Votre rang JcJ"
L["Your quests there: %s."] = "Vos quêtes là-bas : %s."
L["Your ranged weapon between shots."] = "Votre arme à distance entre deux tirs."
L["Your Rank"] = "Votre rang"
L["Your rank this season, and what each rank gives."] = "Votre rang cette saison, et ce que donne chaque rang."
L["Your rank's color (BiS orange)"] = "Couleur de votre rang (orange BiS)"
L["Your recent casts as icons scrolling away from a point, with a bar underneath while you were casting or on the global cooldown. Gaps in the bar are time spent doing nothing. Move it in the HUD Editor."] = "Vos incantations récentes en icônes défilant depuis un point, avec une barre en dessous pendant que vous incantiez ou étiez en temps de recharge global. Les trous dans la barre sont du temps passé à ne rien faire. Déplacez-la dans l'éditeur d'ATH."
