L["Your settings stay as they are."] = "Vos options restent telles quelles."
L["Your settings stay."] = "Vos options restent."
L["Your setup is ready."] = "Votre configuration est prête."
L["Your setup is ready. Reload now to finish?"] = "Votre configuration est prête. Recharger maintenant pour terminer ?"
