L["Your swings from the game's own swing timer, with marks for timing around them."] = "Vos coups d'après le minuteur de coups propre au jeu, avec des repères pour le timing autour."
L["Your swings, with marks to time around them."] = "Vos coups, avec des repères pour le timing."
L["Your talents"] = "Vos talents"
