L["Your target's "] = "Votre cible : "
L["Your target's buffs that last a short while, like Divine Shield, Evasion or Sprint."] = "Les améliorations de courte durée de votre cible, comme Bouclier divin, Évasion ou Sprint."
L["Your target's short buffs and crowd control."] = "Les améliorations courtes et contrôles de foule de votre cible."
L["Your target's short buffs, the crowd control on them and the debuffs you pick, as large icons that keep working in combat."] = "Les améliorations courtes de votre cible, les contrôles de foule sur elle et les affaiblissements que vous choisissez, en grandes icônes qui fonctionnent aussi en combat."
L["Your target's swing, restarted by its last hit on you."] = "Le coup de votre cible, relancé par son dernier coup sur vous."
L["Your tip:"] = "Votre pourboire :"
L["Your top two"] = "Vos deux premiers"
L["Your total played time on this character, from level 1."] = "Votre temps de jeu total sur ce personnage, depuis le niveau 1."
L["Your trinket"] = "Votre bijou"
L["Your trinkets, weapons and ranged slot in a small window when you enter a dungeon or raid, or on a ready check, so a wrong trinket gets noticed before the pull. Drag the window to move it."] = "Vos bijoux, armes et emplacement à distance dans une petite fenêtre quand vous entrez dans un donjon ou un raid, ou lors d'un appel, pour remarquer un mauvais bijou avant le pull. Faites glisser la fenêtre pour la déplacer."
L["Your two trinket slots, movable: left-click to use one, right-click to equip a trinket from your bags outside combat. Move it in the HUD Editor."] = "Vos deux emplacements de bijou, déplaçables : clic gauche pour en utiliser un, clic droit pour équiper un bijou de vos sacs hors combat. Déplacez-les dans l'éditeur d'ATH."
